// Steam metadata discovery. Never assumes a game drive or scans whole drives.
#include "steam_location.h"
#include <shobjidl.h>
#include <algorithm>
#include <fstream>
#include <sstream>
#include <set>
#include <stdexcept>
#include <cctype>
#include <cwctype>
#pragma comment(lib,"advapi32.lib")
#pragma comment(lib,"ole32.lib")
#pragma comment(lib,"uuid.lib")
#pragma comment(lib,"shell32.lib")
namespace omega {namespace {
namespace fs=std::filesystem;
struct Node{std::string text;std::vector<std::pair<std::string,Node>>children;bool object=false;};
std::string lower(std::string x){for(char&c:x)c=char(std::tolower((unsigned char)c));return x;}
struct Parser{const std::string&s;size_t pos=0;Parser(const std::string&v):s(v){if(s.size()>=3&&(unsigned char)s[0]==239&&(unsigned char)s[1]==187&&(unsigned char)s[2]==191)pos=3;}
 void space(){for(;;){while(pos<s.size()&&std::isspace((unsigned char)s[pos]))pos++;if(pos+1<s.size()&&s[pos]=='/'&&s[pos+1]=='/'){while(pos<s.size()&&s[pos]!='\n')pos++;}else break;}}
 std::string token(){space();if(pos>=s.size())throw std::runtime_error("Unexpected end of Steam metadata");char c=s[pos++];if(c=='{'||c=='}')return std::string(1,c);std::string out;if(c=='"'){while(pos<s.size()){c=s[pos++];if(c=='"')return out;if(c=='\\'&&pos<s.size()&&(s[pos]=='\\'||s[pos]=='"'))c=s[pos++];out+=c;}throw std::runtime_error("Unclosed Steam metadata string");}out+=c;while(pos<s.size()&&!std::isspace((unsigned char)s[pos])&&s[pos]!='{'&&s[pos]!='}')out+=s[pos++];return out;}
 Node object(int depth=0,bool nested=false){if(depth>32)throw std::runtime_error("Steam metadata nesting is too deep");Node out;out.object=true;for(;;){space();if(pos==s.size()){if(nested)throw std::runtime_error("Unclosed Steam metadata object");break;}auto key=token();if(key=="}"){if(!nested)throw std::runtime_error("Unexpected Steam metadata brace");break;}if(key=="{")throw std::runtime_error("Missing Steam metadata key");auto value=token();Node n;if(value=="{")n=object(depth+1,true);else if(value=="}")throw std::runtime_error("Missing Steam metadata value");else n.text=value;out.children.emplace_back(key,std::move(n));}return out;}
};
const Node*child(const Node&n,const char*key){for(auto&p:n.children)if(lower(p.first)==lower(key))return&p.second;return nullptr;}
std::string read(const fs::path&p){std::error_code ec;auto size=fs::file_size(p,ec);if(ec||size>16*1024*1024)return {};std::ifstream f(p,std::ios::binary);if(!f)return {};return std::string(std::istreambuf_iterator<char>(f),{});}
void add(std::vector<fs::path>&v,const fs::path&p){if(p.empty())return;auto normalized=p.lexically_normal();if(std::find(v.begin(),v.end(),normalized)==v.end())v.push_back(normalized);}
std::wstring reg(HKEY hive,const wchar_t*key,const wchar_t*value,REGSAM view){HKEY h=nullptr;if(RegOpenKeyExW(hive,key,0,KEY_QUERY_VALUE|view,&h)!=ERROR_SUCCESS)return {};DWORD type=0,size=0;if(RegQueryValueExW(h,value,nullptr,&type,nullptr,&size)!=ERROR_SUCCESS||(type!=REG_SZ&&type!=REG_EXPAND_SZ)||size>65536){RegCloseKey(h);return {};}std::vector<wchar_t>b(size/2+2,0);auto ok=RegQueryValueExW(h,value,nullptr,&type,(BYTE*)b.data(),&size);RegCloseKey(h);if(ok!=ERROR_SUCCESS)return {};std::wstring text(b.data());if(type==REG_EXPAND_SZ){DWORD n=ExpandEnvironmentStringsW(text.c_str(),nullptr,0);if(n&&n<=32768){std::vector<wchar_t>expanded(n);ExpandEnvironmentStringsW(text.c_str(),expanded.data(),n);return expanded.data();}}return text;}
std::wstring env(const wchar_t*key){DWORD n=GetEnvironmentVariableW(key,nullptr,0);if(!n||n>32768)return {};std::vector<wchar_t>b(n);GetEnvironmentVariableW(key,b.data(),n);return b.data();}
}
std::vector<fs::path> steamLibrariesFromVdf(const std::string&text){if(text.size()>16*1024*1024)throw std::runtime_error("Steam library metadata too large");auto tree=Parser(text).object();auto root=child(tree,"libraryfolders");if(!root)return {};std::vector<fs::path>out;for(auto&p:root->children){if(p.first.empty()||p.first.find_first_not_of("0123456789")!=std::string::npos)continue;if(p.second.object){auto path=child(p.second,"path");if(path&&!path->text.empty())add(out,fs::u8path(path->text));}else if(!p.second.text.empty())add(out,fs::u8path(p.second.text));}return out;}
std::string hd2InstallDirFromManifest(const std::string&text){auto tree=Parser(text).object();auto app=child(tree,"AppState");if(!app)return {};auto id=child(*app,"appid"),dir=child(*app,"installdir");if(!id||id->text!="553850"||!dir||dir->text.empty())return {};auto p=fs::u8path(dir->text);if(p.is_absolute()||p.has_root_name())return {};for(auto&piece:p)if(piece==L"..")return {};return dir->text;}
std::wstring validateHd2Folder(const std::wstring&folder){try{fs::path p(folder);std::error_code ec;if(!fs::is_directory(p,ec))return {};auto name=p.filename().wstring();std::transform(name.begin(),name.end(),name.begin(),::towlower);auto root=(name==L"data"||name==L"bin")?p.parent_path():p;auto data=root/L"data";if(!fs::is_regular_file(root/L"bin"/L"helldivers2.exe",ec)||!fs::is_directory(data,ec))return {};if(!fs::is_regular_file(data/L"bundles.nxa",ec)&&!fs::is_regular_file(data/L"game"/L"dl_library.dl_typelib",ec))return {};return fs::weakly_canonical(data).wstring();}catch(...){return {};}}
Hd2Location findHd2InSteamRoots(const std::vector<fs::path>&roots){std::vector<fs::path>libs;for(auto&root:roots){add(libs,root);for(auto&file:{root/L"steamapps"/L"libraryfolders.vdf",root/L"config"/L"libraryfolders.vdf"})try{for(auto&library:steamLibrariesFromVdf(read(file)))add(libs,library);}catch(...){}}
 for(auto&lib:libs){auto manifest=lib/L"steamapps"/L"appmanifest_553850.acf";try{auto install=hd2InstallDirFromManifest(read(manifest));if(install.empty())continue;auto data=validateHd2Folder((lib/L"steamapps"/L"common"/fs::u8path(install)).wstring());if(!data.empty())return {data,L"Steam manifest: "+manifest.wstring()};}catch(...){}}return {};}
Hd2Location findInstalledHd2(){std::vector<fs::path>roots;for(auto view:{REGSAM(KEY_WOW64_64KEY),REGSAM(KEY_WOW64_32KEY)}){add(roots,reg(HKEY_CURRENT_USER,L"Software\\Valve\\Steam",L"SteamPath",view));auto exe=reg(HKEY_CURRENT_USER,L"Software\\Valve\\Steam",L"SteamExe",view);if(!exe.empty())add(roots,fs::path(exe).parent_path());add(roots,reg(HKEY_LOCAL_MACHINE,L"Software\\Valve\\Steam",L"InstallPath",view));}for(auto variable:{L"ProgramFiles(x86)",L"ProgramFiles"}){auto path=env(variable);if(!path.empty())add(roots,fs::path(path)/L"Steam");}return findHd2InSteamRoots(roots);}
std::wstring chooseHd2Folder(HWND owner,const std::wstring&initial){HRESULT init=CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);IFileOpenDialog*dialog=nullptr;auto finish=[&](){if(dialog)dialog->Release();if(SUCCEEDED(init))CoUninitialize();};if(FAILED(CoCreateInstance(CLSID_FileOpenDialog,nullptr,CLSCTX_INPROC_SERVER,IID_PPV_ARGS(&dialog)))){finish();throw std::runtime_error("Windows folder picker could not be opened");}DWORD options=0;dialog->GetOptions(&options);dialog->SetOptions(options|FOS_PICKFOLDERS|FOS_FORCEFILESYSTEM|FOS_PATHMUSTEXIST);dialog->SetTitle(L"Select Helldivers 2 folder (or its data folder)");if(!initial.empty()){IShellItem*start=nullptr;if(SUCCEEDED(SHCreateItemFromParsingName(initial.c_str(),nullptr,IID_PPV_ARGS(&start)))){dialog->SetFolder(start);start->Release();}}auto hr=dialog->Show(owner);if(hr==HRESULT_FROM_WIN32(ERROR_CANCELLED)){finish();return {};}if(FAILED(hr)){finish();throw std::runtime_error("Windows folder selection failed");}IShellItem*item=nullptr;PWSTR path=nullptr;std::wstring selected;if(SUCCEEDED(dialog->GetResult(&item))){if(SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH,&path))){selected=path;CoTaskMemFree(path);}item->Release();}finish();auto data=validateHd2Folder(selected);if(data.empty())throw std::runtime_error("Choose the Helldivers 2 folder containing bin/helldivers2.exe and data, or select its data folder.");return data;}
}
